import{_ as a,o,c as s,a5 as r}from"./chunks/framework.BwlBv862.js";const m=JSON.parse('{"title":"Faça backup e restaure o trabalho local","description":"","frontmatter":{"title":"Faça backup e restaure o trabalho local","docId":"user.preferences.backups","translationKey":"user.preferences.backups","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b2ae789f9c15df21b415b5bc006404dffd60430f193fdaba8cd94931e750eedc","translationRevision":"a593753b59e83fcc2be71388ffba1846f44e9cd8146d706a5f179be6218c37f4","order":20},"headers":[],"relativePath":"pt/user/preferences/backups.md","filePath":"pt/user/preferences/backups.md","lastUpdated":1794611623000}'),i={name:"pt/user/preferences/backups.md"};function t(d,e,c,l,n,u){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="back-up-and-restore-local-work" tabindex="-1">Faça backup e restaure o trabalho local <a class="header-anchor" href="#back-up-and-restore-local-work" aria-label="Permalink to &quot;Faça backup e restaure o trabalho local {#back-up-and-restore-local-work}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Preserve uma configuração funcional antes de atualizações, redefinições ou mudança de computador. Você precisa de armazenamento sob seu controle e tempo para fechar o TikTools corretamente. Não existe um botão universal <strong>Back up everything</strong> na interface atual; use as exportações específicas e uma cópia dos dados com o aplicativo fechado.</p><h2 id="export-reusable-definitions" tabindex="-1">Exporte definições reutilizáveis <a class="header-anchor" href="#export-reusable-definitions" aria-label="Permalink to &quot;Exporte definições reutilizáveis {#export-reusable-definitions}&quot;">​</a></h2><ol><li>Em <strong>Automations</strong>, selecione o perfil desejado e use sua ação de exportação para salvar um arquivo <code>.tikprofile.json</code>. Nomeie-o com a versão do aplicativo e a data.</li><li>Para um único modelo reutilizável, use a área de download/exportação do diálogo de modelos para salvar <code>.tiktemplate.json</code> quando disponível.</li><li>Inspecione o arquivo exportado antes de compartilhá-lo. Modelos podem conter destinos e valores de configuração. Uma exportação de perfil não é uma cópia de saldos, análises, variáveis de execução, arquivos de mídia nem credenciais de conta.</li></ol><h2 id="copy-the-local-data" tabindex="-1">Copie os dados locais <a class="header-anchor" href="#copy-the-local-data" aria-label="Permalink to &quot;Copie os dados locais {#copy-the-local-data}&quot;">​</a></h2><ol><li>Pare a atividade da LIVE e qualquer serviço de colaboração, depois saia do TikTools normalmente. Aguarde o host parar de gravar.</li><li>Localize a raiz de dados ativa. Os padrões são <code>%LOCALAPPDATA%\\TikTools</code> no Windows e <code>~/.local/share/TikTools</code> no Linux, ou <code>TikTools</code> dentro de <code>XDG_DATA_HOME</code> quando configurado. Um <code>TIKTOOLS_HOME</code> personalizado ou uma substituição por diretório altera o local.</li><li>Copie a raiz e quaisquer diretórios de dados, plugins, dados de plugins e armazenamento de plugins substituídos separadamente para uma pasta de backup datada. Copie o diretório completo do banco fechado, incluindo quaisquer arquivos auxiliares SQLite presentes, em vez de selecionar apenas um arquivo <code>.db</code>.</li><li>Preserve os arquivos de áudio referenciados separadamente: ações de áudio mantêm caminhos em vez de importar os bytes dos sons. Registre a versão do aplicativo e os locais dos diretórios personalizados junto do backup.</li><li>Proteja a cópia porque a configuração local pode conter valores privados. A autenticação do Cloud fica no armazenamento de credenciais do sistema operacional e não é transportada por essa cópia de pasta.</li></ol><h2 id="restore-and-verify" tabindex="-1">Restaure e verifique <a class="header-anchor" href="#restore-and-verify" aria-label="Permalink to &quot;Restaure e verifique {#restore-and-verify}&quot;">​</a></h2><p>Com o TikTools fechado, preserve a pasta atual como uma cópia de recuperação separada. Restaure os arquivos salvos nos caminhos desejados e inicie uma versão compatível. Inspecione seleção de perfil, saldos, variáveis e caminhos de mídia antes de reconectar. Para definições portáteis, importe o perfil/modelo exportado por Automations; definições importadas permanecem desativadas até uma ativação explícita.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Resultado esperado, status e recuperação <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Resultado esperado, status e recuperação {#expected-result-status-and-recovery}&quot;">​</a></h2><p>Cópias com o aplicativo fechado e as áreas de importação/exportação citadas são métodos de recuperação disponíveis, sem garantia universal de restauração entre versões. Changes do Cloud não é um backup completo. Se uma versão restaurada rejeitar os dados, pare e retorne à cópia preservada; reinstalar um binário antigo não desfaz uma migração de banco de dados. Consulte <a href="./../updates.html">atualizações</a> e <a href="./troubleshooting.html">solução de problemas</a>.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>Overrides individuais prevalecem sobre <code>TIKTOOLS_HOME</code>: <code>TIKTOOLS_DATA_DIR</code> contém bases; <code>TIKTOOLS_PLUGINS_DIR</code>, pacotes; <code>TIKTOOLS_PLUGIN_DATA_DIR</code>, estado dos plugins; <code>TIKTOOLS_PLUGIN_STORE_DIR</code>, armazenamento de pacotes. <code>TIKTOOLS_LOG_DIR</code> e <code>TIKTOOLS_TEMP_DIR</code> selecionam logs e temporários. Valores relativos usam o diretório de inicialização. Antes da cópia, consulte os caminhos efetivos com <code>tiktools api call system.info --json</code> e registre overrides herdados; copie dados/pacotes/estado com o host parado, incluindo WAL/SHM existentes. Logs são evidências de suporte, não substituem as bases.</p><p><code>system.info</code> informa home/dataDir efetivos; resolva outros diretórios pelo ambiente real de inicialização do host, não outro terminal. Use <code>system.health</code> para ready/pendências analíticas e contadores de entrada LIVE.</p>',14)])])}const f=a(i,[["render",t]]);export{m as __pageData,f as default};
